// The stories the horror room deals. Two corpora fit this shape:
//
//   stories.local.ts   the real one — two-sentence horror stories generated by
//                      tools/build-horror.mjs from a public scrape of
//                      r/TwoSentenceHorror. A personal build only: gitignored
//                      and never committed, because they are thousands of
//                      pieces of fiction by other people, none of whom were asked.
//   stories.sample.ts  placeholder stories written for this repo, so a fresh
//                      clone builds, runs and tests.
//
// The local file wins when it exists. The require is optional (Metro bundles it
// only if the file is there; see metro.config.js), and Jest is pointed away from
// it (jest/no-local-corpus.js), so the suite is the same on every machine.
//
// The subreddit's convention is that the TITLE sets it up and the BODY turns
// it, and the two are stored apart for that reason: the room can hold the
// second one back until you ask for it.
import * as sample from './stories.sample';

export interface Story {
  // The first sentence. Sets it up.
  readonly setup: string;
  // The second. Kept apart so it can be withheld.
  readonly turn: string;
  // Upvotes at scrape time - the only quality signal the data carries.
  readonly score: number;
  readonly year: number;
}

export interface StorySource {
  readonly community: string;
  readonly shortName: string;
}

interface Corpus {
  readonly SOURCE: StorySource;
  readonly MIN_SCORE: number;
  readonly STORIES: readonly Story[];
}

const load = (): { corpus: Corpus; kind: 'full' | 'sample' } => {
  try {
    return { corpus: require('./stories.local') as Corpus, kind: 'full' };
  } catch {
    return { corpus: sample, kind: 'sample' };
  }
};

const loaded = load();

export const SOURCE: StorySource = loaded.corpus.SOURCE;
// The upvote floor the corpus was generated at; every story clears it.
export const MIN_SCORE: number = loaded.corpus.MIN_SCORE;
export const STORIES: readonly Story[] = loaded.corpus.STORIES;
export const CORPUS: 'full' | 'sample' = loaded.kind;
